//! System pasteboard access.

/// Pasteboard types that mark content as secret or short-lived
/// (nspasteboard.org conventions, used by password managers).
const CONCEALED_TYPES: &[&str] = &[
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
    "com.agilebits.onepassword",
];
const IMAGE_TYPES: &[&str] = &["public.png", "public.tiff", "public.jpeg"];
const FILE_URL_TYPE: &str = "public.file-url";

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RawKind {
    Text,
    Files,
    Image,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RawClip {
    pub kind: RawKind,
    pub text: String,
    pub source_app: Option<String>,
    pub concealed: bool,
}

/// Decides what a pasteboard holds from its declared types and contents.
/// Files win over text because Finder also puts the file name on the
/// pasteboard as a string.
pub fn classify(
    types: &[String],
    string: Option<String>,
    files: Vec<String>,
    source_app: Option<String>,
) -> Option<RawClip> {
    let has = |wanted: &[&str]| types.iter().any(|t| wanted.contains(&t.as_str()));
    let concealed = has(CONCEALED_TYPES);
    let (kind, text) = if has(&[FILE_URL_TYPE]) && !files.is_empty() {
        (RawKind::Files, files.join("\n"))
    } else if let Some(s) = string.filter(|s| !s.is_empty()) {
        (RawKind::Text, s)
    } else if has(IMAGE_TYPES) {
        (RawKind::Image, "Image".to_string())
    } else {
        return None;
    };
    Some(RawClip {
        kind,
        text,
        source_app,
        concealed,
    })
}

/// Largest image kept; bigger ones are recorded without a preview.
pub const MAX_IMAGE_BYTES: usize = 16 * 1024 * 1024;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ImageFormat {
    Png,
    Tiff,
}

impl ImageFormat {
    pub fn extension(self) -> &'static str {
        match self {
            ImageFormat::Png => "png",
            ImageFormat::Tiff => "tiff",
        }
    }

    fn uti(self) -> &'static str {
        match self {
            ImageFormat::Png => "public.png",
            ImageFormat::Tiff => "public.tiff",
        }
    }

    pub fn from_extension(ext: &str) -> Option<ImageFormat> {
        match ext.to_ascii_lowercase().as_str() {
            "png" => Some(ImageFormat::Png),
            "tif" | "tiff" => Some(ImageFormat::Tiff),
            _ => None,
        }
    }
}

/// Width and height from a PNG header.
pub fn png_size(bytes: &[u8]) -> Option<(u32, u32)> {
    const SIGNATURE: &[u8] = b"\x89PNG\r\n\x1a\n";
    if bytes.len() < 24 || &bytes[..8] != SIGNATURE || &bytes[12..16] != b"IHDR" {
        return None;
    }
    let read = |i: usize| u32::from_be_bytes([bytes[i], bytes[i + 1], bytes[i + 2], bytes[i + 3]]);
    Some((read(16), read(20)))
}

/// Human description such as `PNG image · 1280×720 · 340 KB`.
pub fn describe_image(bytes: &[u8], format: ImageFormat) -> String {
    let mut parts = vec![match format {
        ImageFormat::Png => "PNG image".to_string(),
        ImageFormat::Tiff => "TIFF image".to_string(),
    }];
    if let Some((w, h)) = png_size(bytes).filter(|_| format == ImageFormat::Png) {
        parts.push(format!("{w}\u{d7}{h}"));
    }
    let kb = bytes.len().div_ceil(1024);
    parts.push(if kb >= 1024 {
        format!("{:.1} MB", kb as f64 / 1024.0)
    } else {
        format!("{kb} KB")
    });
    parts.join(" \u{b7} ")
}

/// Largest formatting kept; bigger rich text is kept as plain text only.
pub const MAX_RICH_BYTES: usize = 2 * 1024 * 1024;

/// How copied text carries its formatting.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RichFormat {
    Rtf,
    /// RTF with attachments, as Pages and TextEdit copy it.
    Rtfd,
    Html,
}

impl RichFormat {
    pub fn extension(self) -> &'static str {
        match self {
            RichFormat::Rtf => "rtf",
            RichFormat::Rtfd => "rtfd",
            RichFormat::Html => "html",
        }
    }

    fn uti(self) -> &'static str {
        match self {
            RichFormat::Rtf => "public.rtf",
            RichFormat::Rtfd => "com.apple.flat-rtfd",
            RichFormat::Html => "public.html",
        }
    }

    pub fn from_extension(ext: &str) -> Option<RichFormat> {
        match ext.to_ascii_lowercase().as_str() {
            "rtf" => Some(RichFormat::Rtf),
            "rtfd" => Some(RichFormat::Rtfd),
            "html" => Some(RichFormat::Html),
            _ => None,
        }
    }
}

/// The formatting of the text on the pasteboard, RTF preferred.
pub fn read_rich() -> Option<(Vec<u8>, RichFormat)> {
    imp::read_rich()
}

/// Replaces the pasteboard contents with text plus its formatting, so apps
/// that paste plain text still get the text.
pub fn write_rich(text: &str, bytes: &[u8], format: RichFormat) -> bool {
    imp::write_rich(text, bytes, format)
}

/// The image on the pasteboard, PNG preferred, if it is not too large.
pub fn read_image() -> Option<(Vec<u8>, ImageFormat)> {
    imp::read_image()
}

/// Replaces the pasteboard contents with an image.
pub fn write_image(bytes: &[u8], format: ImageFormat) -> bool {
    imp::write_image(bytes, format)
}

/// Changes every time any app writes to the pasteboard. Negative when the
/// pasteboard is unavailable.
pub fn change_count() -> i64 {
    imp::change_count()
}

pub fn read() -> Option<RawClip> {
    imp::read()
}

/// Replaces the pasteboard contents with `text`.
pub fn write_text(text: &str) -> bool {
    imp::write_text(text)
}

#[cfg(target_os = "macos")]
mod imp {
    use super::{classify, ImageFormat, RawClip, RichFormat, MAX_IMAGE_BYTES, MAX_RICH_BYTES};
    use objc2::rc::{autoreleasepool, Retained};
    use objc2::runtime::AnyObject;
    use objc2::{class, msg_send};
    use objc2_foundation::{NSArray, NSData, NSString};

    #[link(name = "AppKit", kind = "framework")]
    extern "C" {}

    const STRING_TYPE: &str = "public.utf8-plain-text";
    const FILENAMES_TYPE: &str = "NSFilenamesPboardType";

    #[cfg(test)]
    thread_local! {
        /// Tests use a private named pasteboard instead of the user's.
        pub static TEST_BOARD: std::cell::RefCell<Option<String>> = const { std::cell::RefCell::new(None) };
    }

    fn pasteboard() -> Option<Retained<AnyObject>> {
        #[cfg(test)]
        if let Some(name) = TEST_BOARD.with(|b| b.borrow().clone()) {
            // SAFETY: +pasteboardWithName: takes an NSString and returns a pasteboard.
            return unsafe {
                msg_send![class!(NSPasteboard), pasteboardWithName: &*NSString::from_str(&name)]
            };
        }
        // SAFETY: +generalPasteboard takes no arguments and returns an object or nil.
        unsafe { msg_send![class!(NSPasteboard), generalPasteboard] }
    }

    pub fn change_count() -> i64 {
        autoreleasepool(|_| match pasteboard() {
            // SAFETY: -changeCount returns NSInteger.
            Some(pb) => unsafe {
                let n: isize = msg_send![&*pb, changeCount];
                n as i64
            },
            None => -1,
        })
    }

    pub fn read() -> Option<RawClip> {
        autoreleasepool(|_| {
            let pb = pasteboard()?;
            // SAFETY: -types returns NSArray<NSString *> or nil.
            let types: Option<Retained<NSArray<NSString>>> = unsafe { msg_send![&*pb, types] };
            let types: Vec<String> = types
                .map(|a| a.iter().map(|s| s.to_string()).collect())
                .unwrap_or_default();
            // SAFETY: -stringForType: takes an NSString and returns NSString or nil.
            let string: Option<Retained<NSString>> =
                unsafe { msg_send![&*pb, stringForType: &*NSString::from_str(STRING_TYPE)] };
            // SAFETY: -propertyListForType: returns a property list object or
            // nil; the class is checked before it is treated as an array.
            let plist: Option<Retained<AnyObject>> = unsafe {
                msg_send![&*pb, propertyListForType: &*NSString::from_str(FILENAMES_TYPE)]
            };
            let files = plist.map(|obj| string_array(&obj)).unwrap_or_default();
            classify(
                &types,
                string.map(|s| s.to_string()),
                files,
                frontmost_app(),
            )
        })
    }

    fn string_array(obj: &AnyObject) -> Vec<String> {
        let mut out = Vec::new();
        // SAFETY: class checks guard every cast below.
        unsafe {
            let is_array: bool = msg_send![obj, isKindOfClass: class!(NSArray)];
            if !is_array {
                return out;
            }
            let count: usize = msg_send![obj, count];
            for i in 0..count {
                let item: Option<Retained<AnyObject>> = msg_send![obj, objectAtIndex: i];
                let Some(item) = item else { continue };
                let is_string: bool = msg_send![&*item, isKindOfClass: class!(NSString)];
                if is_string {
                    let s: &NSString = &*(Retained::as_ptr(&item) as *const NSString);
                    out.push(s.to_string());
                }
            }
        }
        out
    }

    fn frontmost_app() -> Option<String> {
        // SAFETY: plain getters returning objects or nil.
        unsafe {
            let ws: Option<Retained<AnyObject>> = msg_send![class!(NSWorkspace), sharedWorkspace];
            let app: Option<Retained<AnyObject>> = msg_send![&*ws?, frontmostApplication];
            let name: Option<Retained<NSString>> = msg_send![&*app?, localizedName];
            name.map(|n| n.to_string())
        }
    }

    pub fn read_image() -> Option<(Vec<u8>, ImageFormat)> {
        autoreleasepool(|_| {
            let pb = pasteboard()?;
            for format in [ImageFormat::Png, ImageFormat::Tiff] {
                // SAFETY: -dataForType: takes an NSString and returns NSData or nil.
                let data: Option<Retained<NSData>> =
                    unsafe { msg_send![&*pb, dataForType: &*NSString::from_str(format.uti())] };
                let Some(data) = data else { continue };
                if data.is_empty() || data.len() > MAX_IMAGE_BYTES {
                    return None;
                }
                return Some((data.to_vec(), format));
            }
            None
        })
    }

    pub fn read_rich() -> Option<(Vec<u8>, RichFormat)> {
        autoreleasepool(|_| {
            let pb = pasteboard()?;
            for format in [RichFormat::Rtf, RichFormat::Rtfd, RichFormat::Html] {
                // SAFETY: -dataForType: takes an NSString and returns NSData or nil.
                let data: Option<Retained<NSData>> =
                    unsafe { msg_send![&*pb, dataForType: &*NSString::from_str(format.uti())] };
                let Some(data) = data else { continue };
                if data.is_empty() || data.len() > MAX_RICH_BYTES {
                    continue;
                }
                return Some((data.to_vec(), format));
            }
            None
        })
    }

    pub fn write_rich(text: &str, bytes: &[u8], format: RichFormat) -> bool {
        autoreleasepool(|_| {
            let Some(pb) = pasteboard() else { return false };
            let data = NSData::with_bytes(bytes);
            // SAFETY: -clearContents returns NSInteger; -setString:forType: and
            // -setData:forType: take an object and an NSString and return BOOL.
            unsafe {
                let _: isize = msg_send![&*pb, clearContents];
                let string_ok: bool = msg_send![
                    &*pb,
                    setString: &*NSString::from_str(text),
                    forType: &*NSString::from_str(STRING_TYPE)
                ];
                let data_ok: bool = msg_send![
                    &*pb,
                    setData: &*data,
                    forType: &*NSString::from_str(format.uti())
                ];
                string_ok && data_ok
            }
        })
    }

    pub fn write_image(bytes: &[u8], format: ImageFormat) -> bool {
        autoreleasepool(|_| {
            let Some(pb) = pasteboard() else { return false };
            let data = NSData::with_bytes(bytes);
            // SAFETY: -clearContents returns NSInteger; -setData:forType:
            // takes NSData and NSString and returns BOOL.
            unsafe {
                let _: isize = msg_send![&*pb, clearContents];
                msg_send![
                    &*pb,
                    setData: &*data,
                    forType: &*NSString::from_str(format.uti())
                ]
            }
        })
    }

    pub fn write_text(text: &str) -> bool {
        autoreleasepool(|_| {
            let Some(pb) = pasteboard() else { return false };
            // SAFETY: -clearContents returns NSInteger; -setString:forType:
            // takes two NSStrings and returns BOOL.
            unsafe {
                let _: isize = msg_send![&*pb, clearContents];
                msg_send![
                    &*pb,
                    setString: &*NSString::from_str(text),
                    forType: &*NSString::from_str(STRING_TYPE)
                ]
            }
        })
    }
}

#[cfg(not(target_os = "macos"))]
mod imp {
    use super::RawClip;

    pub fn change_count() -> i64 {
        -1
    }

    pub fn read() -> Option<RawClip> {
        None
    }

    pub fn write_text(_text: &str) -> bool {
        false
    }

    pub fn read_image() -> Option<(Vec<u8>, super::ImageFormat)> {
        None
    }

    pub fn read_rich() -> Option<(Vec<u8>, super::RichFormat)> {
        None
    }

    pub fn write_rich(_text: &str, _bytes: &[u8], _format: super::RichFormat) -> bool {
        false
    }

    pub fn write_image(_bytes: &[u8], _format: super::ImageFormat) -> bool {
        false
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn types(list: &[&str]) -> Vec<String> {
        list.iter().map(|s| s.to_string()).collect()
    }

    #[test]
    fn plain_text_is_text() {
        let clip = classify(
            &types(&["public.utf8-plain-text"]),
            Some("hello".into()),
            vec![],
            Some("Notes".into()),
        )
        .unwrap();
        assert_eq!(
            clip,
            RawClip {
                kind: RawKind::Text,
                text: "hello".into(),
                source_app: Some("Notes".into()),
                concealed: false
            }
        );
    }

    #[test]
    fn files_win_over_the_file_name_string() {
        let clip = classify(
            &types(&["public.file-url", "public.utf8-plain-text"]),
            Some("a.txt".into()),
            vec!["/tmp/a.txt".into(), "/tmp/b.txt".into()],
            None,
        )
        .unwrap();
        assert_eq!(clip.kind, RawKind::Files);
        assert_eq!(clip.text, "/tmp/a.txt\n/tmp/b.txt");
    }

    #[test]
    fn file_url_type_without_paths_falls_back_to_text() {
        let clip = classify(&types(&["public.file-url"]), Some("x".into()), vec![], None).unwrap();
        assert_eq!(clip.kind, RawKind::Text);
    }

    #[test]
    fn image_only_pasteboard_is_an_image() {
        let clip = classify(&types(&["public.tiff"]), None, vec![], None).unwrap();
        assert_eq!((clip.kind, clip.text.as_str()), (RawKind::Image, "Image"));
        // Text copied alongside an image (e.g. from a browser) is kept as text.
        let clip = classify(
            &types(&["public.png"]),
            Some("caption".into()),
            vec![],
            None,
        )
        .unwrap();
        assert_eq!(clip.kind, RawKind::Text);
    }

    #[test]
    fn password_manager_markers_are_flagged() {
        for marker in CONCEALED_TYPES {
            let clip = classify(
                &types(&["public.utf8-plain-text", marker]),
                Some("hunter2".into()),
                vec![],
                None,
            )
            .unwrap();
            assert!(clip.concealed, "{marker}");
        }
    }

    #[test]
    fn empty_or_unknown_content_is_nothing() {
        assert_eq!(classify(&[], None, vec![], None), None);
        assert_eq!(
            classify(
                &types(&["public.utf8-plain-text"]),
                Some(String::new()),
                vec![],
                None
            ),
            None
        );
        assert_eq!(
            classify(&types(&["com.example.custom"]), None, vec![], None),
            None
        );
    }

    // Read-only: tests never write to the user's real pasteboard.
    #[cfg(target_os = "macos")]
    #[test]
    fn reads_the_live_pasteboard_without_changing_it() {
        let before = change_count();
        assert!(before >= 0, "the general pasteboard is available");
        if let Some(clip) = read() {
            assert!(!clip.text.is_empty());
        }
        // Reading must not count as a change (another app copying during
        // the test is the only way this could differ).
        assert!(change_count() - before <= 1);
    }

    fn png(w: u32, h: u32, extra: usize) -> Vec<u8> {
        let mut b = b"\x89PNG\r\n\x1a\n\0\0\0\x0dIHDR".to_vec();
        b.extend_from_slice(&w.to_be_bytes());
        b.extend_from_slice(&h.to_be_bytes());
        b.resize(b.len() + extra, 0);
        b
    }

    #[test]
    fn png_headers_give_the_size() {
        assert_eq!(png_size(&png(1280, 720, 0)), Some((1280, 720)));
        assert_eq!(png_size(b"not a png at all, really not"), None);
        assert_eq!(png_size(&png(1, 1, 0)[..20]), None);
    }

    #[test]
    fn images_are_described_with_size_and_dimensions() {
        assert_eq!(
            describe_image(&png(1280, 720, 340 * 1024), ImageFormat::Png),
            "PNG image \u{b7} 1280\u{d7}720 \u{b7} 341 KB"
        );
        assert_eq!(
            describe_image(&vec![0; 3 * 1024 * 1024], ImageFormat::Tiff),
            "TIFF image \u{b7} 3.0 MB"
        );
        assert_eq!(
            describe_image(&[1, 2], ImageFormat::Png),
            "PNG image \u{b7} 1 KB"
        );
    }

    #[test]
    fn rich_formats_map_to_extensions() {
        for f in [RichFormat::Rtf, RichFormat::Rtfd, RichFormat::Html] {
            assert_eq!(RichFormat::from_extension(f.extension()), Some(f));
        }
        assert_eq!(RichFormat::from_extension("txt"), None);
    }

    #[test]
    fn formats_map_to_extensions() {
        for f in [ImageFormat::Png, ImageFormat::Tiff] {
            assert_eq!(ImageFormat::from_extension(f.extension()), Some(f));
        }
        assert_eq!(ImageFormat::from_extension("TIF"), Some(ImageFormat::Tiff));
        assert_eq!(ImageFormat::from_extension("jpg"), None);
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn formatted_text_round_trips_through_a_private_pasteboard() {
        imp::TEST_BOARD.with(|b| *b.borrow_mut() = Some("dev.litenotch.tests.rich".into()));
        let rtf = br"{\rtf1\ansi{\fonttbl\f0 Helvetica;}\f0\b Bold\b0  words}";
        assert!(write_rich("Bold words", rtf, RichFormat::Rtf));
        let clip = read().expect("text on the test pasteboard");
        assert_eq!(
            (clip.kind, clip.text.as_str()),
            (RawKind::Text, "Bold words")
        );
        assert_eq!(read_rich(), Some((rtf.to_vec(), RichFormat::Rtf)));

        let html = b"<b>Bold</b> words";
        assert!(write_rich("Bold words", html, RichFormat::Html));
        assert_eq!(read_rich(), Some((html.to_vec(), RichFormat::Html)));

        assert!(write_text("plain"));
        assert_eq!(read_rich(), None);
        imp::TEST_BOARD.with(|b| *b.borrow_mut() = None);
    }
}
